// ── Steward Memory (Persistent Store) ──
// JSON-backed storage for scan records, corrections, and learned patterns.
// No native dependencies — uses fs read/write.

import { StewardRecord, TrainingSample, StewardConfig, DEFAULT_STEWARD_CONFIG } from "./types";
import { logger } from "@/lib/logger";
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "fs";
import { dirname } from "path";

interface MemoryData {
  scans: StewardRecord[];
  training: TrainingSample[];
  migrations: number;
}

export class StewardMemory {
  private config: StewardConfig;
  private data: MemoryData;
  private dirty: boolean = false;
  private flushTimer: ReturnType<typeof setTimeout> | null = null;

  constructor(config?: Partial<StewardConfig>) {
    this.config = { ...DEFAULT_STEWARD_CONFIG, ...config };
    this.data = this.load();
  }

  // ── Load from disk ──

  private load(): MemoryData {
    try {
      const path = this.config.storage_path;
      if (!existsSync(path)) {
        logger.info({ msg: "Steward memory initialized (new)", path });
        return { scans: [], training: [], migrations: 0 };
      }
      const raw = readFileSync(path, "utf-8");
      const parsed = JSON.parse(raw) as MemoryData;
      logger.info({ msg: "Steward memory loaded", scans: parsed.scans.length, training: parsed.training.length });
      return parsed;
    } catch (err) {
      logger.warn({ msg: "Failed to load steward memory, starting fresh", error: String(err) });
      return { scans: [], training: [], migrations: 0 };
    }
  }

  // ── Save to disk (debounced) ──

  private save(): void {
    this.dirty = true;
    if (this.flushTimer) return;

    this.flushTimer = setTimeout(() => {
      this.flushTimer = null;
      if (!this.dirty) return;
      try {
        const path = this.config.storage_path;
        const dir = dirname(path);
        if (!existsSync(dir)) {
          mkdirSync(dir, { recursive: true });
        }
        writeFileSync(path, JSON.stringify(this.data, null, 2), "utf-8");
        this.dirty = false;
      } catch (err) {
        logger.warn({ msg: "Failed to save steward memory", error: String(err) });
      }
    }, 2000);
  }

  // ── Record a scan observation ──

  recordScan(record: StewardRecord): void {
    this.data.scans.push(record);

    // Update training samples from corrections
    for (const c of record.corrections) {
      const pattern = `${c.reason.split(":")[0].trim()}`;
      const existing = this.data.training.find((t) => t.pattern === pattern);
      if (existing) {
        existing.count++;
        existing.last_seen = record.timestamp;
        existing.fix_rate = (existing.fix_rate * (existing.count - 1) + c.confidence) / existing.count;
      } else {
        this.data.training.push({
          pattern,
          count: 1,
          last_seen: record.timestamp,
          fix_rate: c.confidence,
        });
      }
    }

    // Trim old scans (keep last 500)
    if (this.data.scans.length > 500) {
      this.data.scans = this.data.scans.slice(-500);
    }

    this.save();
  }

  // ── Query helpers ──

  getRecentScans(limit: number = 20): StewardRecord[] {
    return this.data.scans.slice(-limit).reverse();
  }

  getTrainingData(): TrainingSample[] {
    return [...this.data.training];
  }

  /** Get price stats for a category across all scanned items */ 
  getCategoryStats(_category: string): { prices: number[]; mean: number; std: number } | null {
    const prices = this.data.scans
      .flatMap((_s) => {
        // We can't directly get individual item prices from records easily
        // without storing them. For now, return null — this gets filled
        // in Phase 3 (optimizer).
        return [] as number[];
      });

    if (prices.length === 0) return null;

    const mean = prices.reduce((a, b) => a + b, 0) / prices.length;
    const variance = prices.reduce((sum, p) => sum + (p - mean) ** 2, 0) / prices.length;
    return { prices, mean, std: Math.sqrt(variance) };
  }

  /** Total corrections made */ 
  getTotalCorrections(): number {
    return this.data.scans.reduce((sum, s) => sum + s.corrections.length, 0);
  }

  /** Average quality score across recent scans */ 
  getAverageQuality(limit: number = 50): number {
    const recent = this.data.scans.slice(-limit);
    if (recent.length === 0) return 0;
    return Math.round(recent.reduce((sum, s) => sum + s.quality_score, 0) / recent.length);
  }

  /** Get summary report */ 
  getSummary(): string {
    const total = this.data.scans.length;
    const corrections = this.getTotalCorrections();
    const avgQuality = this.getAverageQuality();
    const topPatterns = [...this.data.training]
      .sort((a, b) => b.count - a.count)
      .slice(0, 5);

    let report = `Steward Agent Report\n`;
    report += `━━━━━━━━━━━━━━━━━━━━\n`;
    report += `Scans observed: ${total}\n`;
    report += `Corrections applied: ${corrections}\n`;
    report += `Avg quality score: ${avgQuality}%\n`;
    report += `Training patterns: ${this.data.training.length}\n`;
    if (topPatterns.length > 0) {
      report += `Top patterns:\n`;
      for (const p of topPatterns) {
        report += `  • ${p.pattern} (${p.count}x, fix rate: ${(p.fix_rate * 100).toFixed(0)}%)\n`;
      }
    }
    return report;
  }

  /** Force immediate flush */ 
  flush(): void {
    if (this.flushTimer) {
      clearTimeout(this.flushTimer);
      this.flushTimer = null;
    }
    if (this.dirty) {
      this.save();
    }
  }
}

// Singleton instance (lazy)
let _instance: StewardMemory | null = null;

export function getStewardMemory(config?: Partial<StewardConfig>): StewardMemory {
  if (!_instance) {
    _instance = new StewardMemory(config);
  }
  return _instance;
}
