// ── Steward Validator ──
// Validates OCR results for quality and sanity.
// Every check produces a structured result that feeds the learning core.

import { StewardItem, ValidationCheck, ItemValidation } from "./types";

// ── Known category price profiles (learned from training) ──
// These are initial defaults; the optimizer updates them over time.
interface PriceProfile {
  mean: number;
  std: number;
  min: number;
  max: number;
  samples: number;
}

const DEFAULT_PRICE_PROFILES: Record<string, PriceProfile> = {
  "appetizers":   { mean: 8.50,  std: 4.00, min: 2.00,  max: 20.00, samples: 50 },
  "starters":     { mean: 8.50,  std: 4.00, min: 2.00,  max: 20.00, samples: 30 },
  "soups":        { mean: 6.00,  std: 2.50, min: 3.00,  max: 14.00, samples: 20 },
  "salads":       { mean: 10.00, std: 4.00, min: 4.00,  max: 18.00, samples: 20 },
  "main courses": { mean: 18.00, std: 8.00, min: 6.00,  max: 45.00, samples: 80 },
  "entrees":      { mean: 18.00, std: 8.00, min: 6.00,  max: 45.00, samples: 50 },
  "mains":        { mean: 18.00, std: 8.00, min: 6.00,  max: 45.00, samples: 60 },
  "desserts":     { mean: 8.00,  std: 3.50, min: 3.00,  max: 15.00, samples: 40 },
  "drinks":       { mean: 5.00,  std: 3.00, min: 1.50,  max: 14.00, samples: 30 },
  "beverages":    { mean: 5.00,  std: 3.00, min: 1.50,  max: 14.00, samples: 20 },
  "sides":        { mean: 5.00,  std: 2.00, min: 2.00,  max: 10.00, samples: 20 },
  "kids":         { mean: 7.00,  std: 2.50, min: 3.00,  max: 12.00, samples: 15 },
  "lunch":        { mean: 12.00, std: 5.00, min: 5.00,  max: 25.00, samples: 25 },
  "dinner":       { mean: 20.00, std: 10.00,min: 8.00,  max: 50.00, samples: 30 },
  "noodles":      { mean: 12.00, std: 5.00, min: 5.00,  max: 25.00, samples: 20 },
  "sushi":        { mean: 15.00, std: 7.00, min: 8.00,  max: 35.00, samples: 20 },
};

// ── Known garbage name patterns ──
const GARBAGE_NAME_PATTERNS = [
  /^[•·*\-–—]+$/,                      // only bullets
  /^\d+$/,                              // only digits
  /^(mon|tue|wed|thu|fri|sat|sun)/i,    // day names
  /(hours|phone|email|address|fax)/i,    // contact info
  /(visa|mastercard|amex|cash|credit)/i, // payment
  /^(open|closed|welcome|thank|please)/i, // footer
  /(allergen|gluten|dairy|contains)/i,   // disclaimers
  /tax|tip|gratuity|service\s*charge/i,  // billing
  /page\s+\d+\s*of\s*\d+/i,              // page numbers
];

// ── Known description quality patterns ──
const BAD_DESC_PATTERNS = [
  /^\.\.\.$/,
  /^n\/a$/i,
  /^none$/i,
  /^see\s+above/i,
  /^same\s+as/i,
  /^ask\s+(server|staff|waiter)/i,
];

// ── Price → category mapping helpers ──
function priceZScore(price: number, profile: PriceProfile): number {
  if (profile.std === 0) return 0;
  return (price - profile.mean) / profile.std;
}

function findBestCategory(price: number, _name: string): string | null {
  // Try to find a category whose price range fits
  for (const [cat, prof] of Object.entries(DEFAULT_PRICE_PROFILES)) {
    if (price >= prof.min && price <= prof.max) return cat;
  }
  return null;
}

// ── Validators ──

function validatePrice(
  item: StewardItem,
  _index: number
): ValidationCheck[] {
  const checks: ValidationCheck[] = [];
  const price = item.price;

  if (price === null || price === undefined) {
    checks.push({
      field: "price",
      passed: false,
      severity: "warn",
      message: "Item has no price",
      original_value: null,
    });
    return checks;
  }

  if (typeof price !== "number" || isNaN(price)) {
    checks.push({
      field: "price",
      passed: false,
      severity: "error",
      message: "Price is not a valid number",
      original_value: price,
    });
    return checks;
  }

  if (price <= 0) {
    checks.push({
      field: "price",
      passed: false,
      severity: "error",
      message: "Price is zero or negative",
      original_value: price,
    });
    return checks;
  }

  // Price too high (> $200 is almost certainly a misread)
  if (price > 200) {
    checks.push({
      field: "price",
      passed: false,
      severity: "error",
      message: `Price $${price.toFixed(2)} is unreasonably high — likely a decimal misread (e.g. missing '.' before digits)`,
      original_value: price,
      suggested_value: price / 100,
    });
    return checks;
  }

  // Price too high for a single dish
  if (price > 100) {
    checks.push({
      field: "price",
      passed: false,
      severity: "warn",
      message: `Price $${price.toFixed(2)} is very high — possible OCR decimal error`,
      original_value: price,
      suggested_value: price > 1000 ? price / 100 : price / 10,
    });
  }

  // Category-specific price check
  const cat = (item.category || "other").toLowerCase();
  const profile = DEFAULT_PRICE_PROFILES[cat];
  if (profile) {
    const z = priceZScore(price, profile);
    if (z > 2.5) {
      checks.push({
        field: "price",
        passed: false,
        severity: "warn",
        message: `Price $${price.toFixed(2)} is ${z.toFixed(1)}σ above mean for "${cat}" ($${profile.mean.toFixed(2)}±${profile.std.toFixed(2)})`,
        original_value: price,
        suggested_value: profile.mean + profile.std,
      });
    } else if (profile.max && price > profile.max * 2) {
      checks.push({
        field: "price",
        passed: false,
        severity: "warn",
        message: `Price $${price.toFixed(2)} exceeds max for "${cat}" ($${profile.max.toFixed(2)}) — possible decimal error`,
        original_value: price,
        suggested_value: price > 100 ? price / 100 : price,
      });
    } else {
      checks.push({
        field: "price",
        passed: true,
        severity: "info",
        message: `Price $${price.toFixed(2)} is within normal range for "${cat}"`,
      });
    }
  } else {
    checks.push({
      field: "price",
      passed: true,
      severity: "info",
      message: `Price $${price.toFixed(2)} (uncategorized)`,
    });
  }

  return checks;
}

function validateName(item: StewardItem, _index: number): ValidationCheck[] {
  const checks: ValidationCheck[] = [];
  const name = (item.name || "").trim();

  if (!name) {
    checks.push({
      field: "name",
      passed: false,
      severity: "error",
      message: "Item has no name",
    });
    return checks;
  }

  // Check for garbage patterns
  for (const pattern of GARBAGE_NAME_PATTERNS) {
    if (pattern.test(name)) {
      checks.push({
        field: "name",
        passed: false,
        severity: "error",
        message: `Name "${name}" matches garbage pattern: ${pattern}`,
        original_value: name,
      });
      return checks; // fail fast on clear garbage
    }
  }

  // Trailing punctuation artifacts (period, comma, colon, semicolon)
  const trailingPunctMatch = name.match(/[.,;:]$/);
  if (trailingPunctMatch) {
    checks.push({
      field: "name",
      passed: false,
      severity: "warn",
      message: `Name "${name}" has trailing punctuation — likely OCR artifact`,
      original_value: name,
      suggested_value: name.replace(/[.,;:]+$/, "").trim(),
    });
  }

  // Trailing dot + space pattern like "Tiramisu ."
  if (/\.\s*$/.test(name) && !name.endsWith(".")) {
    checks.push({
      field: "name",
      passed: false,
      severity: "warn",
      message: `Name "${name}" has trailing dot — likely OCR artifact`,
      original_value: name,
      suggested_value: name.replace(/\.\s*$/, "").trim(),
    });
  }

  // Too short
  if (name.length < 3) {
    checks.push({
      field: "name",
      passed: false,
      severity: "warn",
      message: `Name "${name}" is very short (${name.length} chars)`,
    });
  }

  // Name has leading "The " — uncommon for dish names
  if (/^the\s+/i.test(name) && name.length < 15) {
    checks.push({
      field: "name",
      passed: false,
      severity: "info",
      message: `Name "${name}" starts with "The" — verify if correct`,
    });
  }

  // Name is all lowercase — uncommon for restaurant dish names
  if (name === name.toLowerCase() && name.length > 3) {
    checks.push({
      field: "name",
      passed: false,
      severity: "info",
      message: `Name "${name}" is all lowercase — verify capitalization`,
    });
  }

  if (checks.length === 0) {
    checks.push({
      field: "name",
      passed: true,
      severity: "info",
      message: `Name "${name}" looks valid`,
    });
  }

  return checks;
}

function validateDescription(
  item: StewardItem,
  _index: number
): ValidationCheck[] {
  const checks: ValidationCheck[] = [];
  const desc = (item.description || "").trim();

  if (!desc) {
    checks.push({
      field: "description",
      passed: false,
      severity: "warn",
      message: "Item has no description",
    });
    return checks;
  }

  // Check for bad description patterns
  for (const pattern of BAD_DESC_PATTERNS) {
    if (pattern.test(desc)) {
      checks.push({
        field: "description",
        passed: false,
        severity: "warn",
        message: `Description "${desc}" matches known bad pattern`,
        original_value: desc,
        suggested_value: "",
      });
      return checks;
    }
  }

  // Description contains the dish name verbatim — likely a copy-paste error
  const nameWords = (item.name || "").toLowerCase().split(/\s+/);
  const descWords = desc.toLowerCase().split(/\s+/);
  const sharedWords = nameWords.filter((w) => w.length > 3 && descWords.includes(w));
  if (sharedWords.length >= 2) {
    checks.push({
      field: "description",
      passed: false,
      severity: "warn",
      message: `Description shares ${sharedWords.length} significant words with name — possible duplication`,
      original_value: desc,
    });
  }

  // Description too short to be meaningful
  if (desc.length < 10) {
    checks.push({
      field: "description",
      passed: false,
      severity: "info",
      message: `Description is very short (${desc.length} chars)`,
    });
  }

  // Description has numbers that look like prices
  const priceInDesc = desc.match(/\$\s*\d+(?:\.\d{2})?/);
  if (priceInDesc) {
    checks.push({
      field: "description",
      passed: false,
      severity: "warn",
      message: `Description contains price-like text "${priceInDesc[0]}" — possible mis-assigned data`,
      original_value: priceInDesc[0],
    });
  }

  if (checks.length === 0) {
    checks.push({
      field: "description",
      passed: true,
      severity: "info",
      message: "Description looks valid",
    });
  }

  return checks;
}

function validateCategory(item: StewardItem, _index: number): ValidationCheck[] {
  const checks: ValidationCheck[] = [];
  const cat = (item.category || "").toLowerCase().trim();

  if (!cat) {
    checks.push({
      field: "category",
      passed: false,
      severity: "info",
      message: "Item has no category",
    });
    return checks;
  }

  const knownCategories = new Set(Object.keys(DEFAULT_PRICE_PROFILES));
  if (!knownCategories.has(cat)) {
    checks.push({
      field: "category",
      passed: false,
      severity: "warn",
      message: `Category "${cat}" is not in known list — consider normalizing`,
      original_value: cat,
      suggested_value: findBestCategory(item.price ?? 0, item.name ?? "") || "other",
    });
  }

  if (checks.length === 0) {
    checks.push({
      field: "category",
      passed: true,
      severity: "info",
      message: `Category "${cat}" is recognized`,
    });
  }

  return checks;
}

function validateConfidence(item: StewardItem, _index: number): ValidationCheck[] {
  const checks: ValidationCheck[] = [];
  const conf = item.confidence;

  if (conf === undefined || conf === null) {
    checks.push({
      field: "confidence",
      passed: false,
      severity: "info",
      message: "No confidence score",
    });
    return checks;
  }

  if (conf < 0.3) {
    checks.push({
      field: "confidence",
      passed: false,
      severity: "warn",
      message: `Confidence ${(conf * 100).toFixed(0)}% is very low — item may be unreliable`,
    });
  } else if (conf < 0.6) {
    checks.push({
      field: "confidence",
      passed: false,
      severity: "info",
      message: `Confidence ${(conf * 100).toFixed(0)}% is moderate — verify quality`,
    });
  } else {
    checks.push({
      field: "confidence",
      passed: true,
      severity: "info",
      message: `Confidence ${(conf * 100).toFixed(0)}% is acceptable`,
    });
  }

  return checks;
}

// ── Public API ──

export function validateItem(
  item: StewardItem,
  index: number
): ItemValidation {
  const allChecks: ValidationCheck[] = [
    ...validatePrice(item, index),
    ...validateName(item, index),
    ...validateDescription(item, index),
    ...validateCategory(item, index),
    ...validateConfidence(item, index),
  ];

  const errors = allChecks.filter((c) => c.severity === "error");
  const warnings = allChecks.filter((c) => c.severity === "warn");

  let overall: "pass" | "warn" | "fail";
  if (errors.length > 0) {
    overall = "fail";
  } else if (warnings.length > 0) {
    overall = "warn";
  } else {
    overall = "pass";
  }

  return {
    item_index: index,
    item_name: item.name || `Item #${index}`,
    checks: allChecks,
    overall,
  };
}

export function validateItems(items: StewardItem[]): ItemValidation[] {
  return items.map((item, index) => validateItem(item, index));
}

export function computeQualityScore(validations: ItemValidation[]): number {
  if (validations.length === 0) return 0;

  let totalPassed = 0;
  let totalChecks = 0;

  for (const v of validations) {
    for (const c of v.checks) {
      totalChecks++;
      if (c.passed) totalPassed++;
    }
  }

  return totalChecks > 0 ? Math.round((totalPassed / totalChecks) * 100) : 0;
}

export { DEFAULT_PRICE_PROFILES };
