// ── Steward Corrector ──
// Automatically fixes common OCR artifacts and data quality issues.
// Every correction is logged for the training core.

import { StewardItem, Correction } from "./types";
import { DEFAULT_PRICE_PROFILES } from "./validator";

/** Fix trailing dot/period/punctuation in names */ 
function fixTrailingPunctuation(
  item: StewardItem,
  index: number
): Correction | null {
  const name = (item.name || "").trim();
  
  // "Tiramisu ." → "Tiramisu"
  const trailingDotSpace = name.match(/^(.+?)\s*\.\s*$/);
  if (trailingDotSpace) {
    const fixed = trailingDotSpace[1].trim();
    if (fixed.length >= 2) {
      return {
        item_index: index,
        field: "name",
        reason: `Trailing dot artifact: "${name}" → "${fixed}"`,
        old_value: name,
        new_value: fixed,
        confidence: 0.95,
      };
    }
  }

  // "DishName." → "DishName" (period at end)
  const trailingPunct = name.match(/^(.+?)[.,;:]$/);
  if (trailingPunct) {
    const fixed = trailingPunct[1].trim();
    if (fixed.length >= 2 && /[a-zA-Z]/.test(fixed)) {
      return {
        item_index: index,
        field: "name",
        reason: `Trailing punctuation: "${name}" → "${fixed}"`,
        old_value: name,
        new_value: fixed,
        confidence: 0.9,
      };
    }
  }

  return null;
}

/** Fix price decimal misreads where Tesseract drops decimal point */ 
function fixPriceDecimal(
  item: StewardItem,
  index: number
): Correction | null {
  const price = item.price;
  if (price === null || price === undefined || typeof price !== "number") {
    return null;
  }
  if (price <= 0 || isNaN(price)) return null;

  const cat = (item.category || "other").toLowerCase();
  const profile = DEFAULT_PRICE_PROFILES[cat];

  // Price is suspiciously high with no decimal: e.g. 95 when it should be 0.95
  if (price >= 100) {
    const candidates: { value: number; reason: string }[] = [];

    if (price >= 1000) {
      candidates.push({ value: price / 100, reason: "missing '.' before last 2 digits" });
    }
    candidates.push({ value: price / 100, reason: "missing decimal point" });
    if (price >= 50) {
      candidates.push({ value: price / 10, reason: "missing '.' before last digit" });
    }

    let bestCandidate: { value: number; reason: string } | null = null;
    let bestScore = -Infinity;

    for (const c of candidates) {
      if (c.value <= 0 || c.value > 200) continue;
      if (!profile) {
        if (c.value >= 1 && c.value <= 50) {
          bestCandidate = c;
          bestScore = 1;
          break;
        }
        continue;
      }
      const z = Math.abs((c.value - profile.mean) / (profile.std || 1));
      const score = -z;
      if (score > bestScore && c.value >= profile.min * 0.5 && c.value <= profile.max * 2) {
        bestScore = score;
        bestCandidate = c;
      }
    }

    if (bestCandidate) {
      return {
        item_index: index,
        field: "price",
        reason: `Price $${price.toFixed(2)} looks like ${bestCandidate.reason} — correcting to $${bestCandidate.value.toFixed(2)}`,
        old_value: price,
        new_value: parseFloat(bestCandidate.value.toFixed(2)),
        confidence: Math.min(0.95, Math.max(0.6, 1 - Math.abs(bestScore) / 10)),
      };
    }
  }

  // Minor price in a category where it's way too low (e.g. "$1.00" for a main course)
  if (profile && price >= 0.5 && price < profile.min * 0.5) {
    const shiftedPrice = price * 10;
    if (shiftedPrice >= profile.min * 0.8 && shiftedPrice <= profile.max * 1.5) {
      return {
        item_index: index,
        field: "price",
        reason: `Price $${price.toFixed(2)} is too low for "${cat}" — shifted decimal? Trying $${shiftedPrice.toFixed(2)}`,
        old_value: price,
        new_value: parseFloat(shiftedPrice.toFixed(2)),
        confidence: 0.7,
      };
    }
  }

  return null;
}

/** Fix price that's a statistical outlier for its category.
 *  E.g. $95 for a dessert (dessert mean=$8±3.50, z=24.9σ).
 *  Tries dividing by 10 or 100 to find a reasonable price. */
function fixPriceOutlier(
  item: StewardItem,
  index: number
): Correction | null {
  const price = item.price;
  if (price === null || price === undefined || typeof price !== "number") return null;
  if (price <= 0 || isNaN(price)) return null;

  const cat = (item.category || "other").toLowerCase();
  const profile = DEFAULT_PRICE_PROFILES[cat];
  if (!profile) return null;

  // Only act on clear outliers (z > 4σ)
  const z = Math.abs((price - profile.mean) / (profile.std || 1));
  if (z < 4) return null;

  // Try dividing by 10 and 100
  const candidates: { value: number; reason: string }[] = [];
  if (price >= 10) candidates.push({ value: price / 10, reason: "missing decimal point" });
  if (price >= 100) candidates.push({ value: price / 100, reason: "missing '.' before last 2 digits" });

  let bestCandidate: { value: number; reason: string } | null = null;
  let bestZ = Infinity;

  for (const c of candidates) {
    if (c.value <= 0 || c.value > 200) continue;
    const newZ = Math.abs((c.value - profile.mean) / (profile.std || 1));
    // Must be within 2σ of the category mean
    if (newZ < bestZ && newZ < 2) {
      bestZ = newZ;
      bestCandidate = c;
    }
  }

  if (!bestCandidate) return null;

  // Don't correct if the price is already a plausible value for the category
  // (e.g. $95 for main courses might be real for a high-end steak)
  const alreadyReasonable = price >= profile.min && price <= profile.max;
  if (alreadyReasonable) return null;

  // Boost confidence if the corrected price is a much better fit than the original
  const confidence = Math.min(0.95, Math.max(0.65, 1 - (bestZ / 6)));

  return {
    item_index: index,
    field: "price",
    reason: `Price $${price.toFixed(2)} is ${z.toFixed(1)}σ outlier for "${cat}" — correcting to $${bestCandidate.value.toFixed(2)}`,
    old_value: price,
    new_value: parseFloat(bestCandidate.value.toFixed(2)),
    confidence,
  };
}

/** Fix description that looks like it belongs to a different dish */ 
function fixDescriptionMismatch(
  item: StewardItem,
  index: number,
  allItems: StewardItem[]
): Correction | null {
  const desc = (item.description || "").trim().toLowerCase();
  const name = (item.name || "").trim();
  if (!desc || !name) return null;

  const nameKeyWords = name
    .toLowerCase()
    .split(/\s+/)
    .filter((w) => w.length > 4 && !["with", "and", "the", "from", "sauce"].includes(w));

  for (let j = 0; j < allItems.length; j++) {
    if (j === index) continue;
    const otherName = (allItems[j].name || "").toLowerCase();
    const otherKeyWords = otherName
      .split(/\s+/)
      .filter((w) => w.length > 4 && !["with", "and", "the", "from", "sauce"].includes(w));

    if (otherKeyWords.length === 0) continue;

    const otherMatches = otherKeyWords.filter((w) => desc.includes(w)).length;
    const otherRatio = otherKeyWords.length > 0 ? otherMatches / otherKeyWords.length : 0;

    const thisMatches = nameKeyWords.filter((w) =>
      (allItems[j].description || "").toLowerCase().includes(w)
    ).length;
    const thisRatio = nameKeyWords.length > 0 ? thisMatches / nameKeyWords.length : 0;

    if (otherRatio > 0.5 && thisRatio > 0.5) {
      const otherDesc = allItems[j].description || "";
      if (otherDesc.length > 0) {
        return {
          item_index: index,
          field: "description",
          reason: `Description appears swapped with "${otherName.slice(0, 30)}"`,
          old_value: item.description,
          new_value: otherDesc,
          confidence: Math.min(0.9, 0.5 + otherRatio * 0.4),
        };
      }
    }
  }

  return null;
}

/** Fix empty/placeholder descriptions */ 
function fixEmptyDescription(
  item: StewardItem,
  index: number
): Correction | null {
  const desc = (item.description || "").trim();
  if (desc) return null;

  const name = (item.name || "").trim();
  const parenMatch = name.match(/^(.+?)\s*\((.+?)\)\s*$/);
  if (parenMatch) {
    return {
      item_index: index,
      field: "description",
      reason: `Extracted parenthesized description from name`,
      old_value: "",
      new_value: parenMatch[2].trim(),
      confidence: 0.85,
    };
  }

  return null;
}

/** Fix category using price-based heuristics */ 
function fixCategory(
  item: StewardItem,
  index: number
): Correction | null {
  const price = item.price;
  const cat = (item.category || "").toLowerCase().trim();
  if (!cat) return null;

  if (Object.keys(DEFAULT_PRICE_PROFILES).includes(cat)) return null;

  if (price !== null && price !== undefined && typeof price === "number" && price > 0) {
    let bestCat = "other";
    let bestZ = Infinity;
    for (const [pc, prof] of Object.entries(DEFAULT_PRICE_PROFILES)) {
      const z = Math.abs((price - prof.mean) / (prof.std || 1));
      if (z < bestZ) {
        bestZ = z;
        bestCat = pc;
      }
    }
    if (bestCat !== "other" && bestZ < 3) {
      return {
        item_index: index,
        field: "category",
        reason: `Unrecognized category "${cat}" — mapped to "${bestCat}" by price`,
        old_value: item.category,
        new_value: bestCat,
        confidence: Math.max(0.5, 1 - bestZ / 6),
      };
    }
  }

  return null;
}

/** Fix all-caps names that should be title case */ 
function fixTitleCase(
  item: StewardItem,
  index: number
): Correction | null {
  const name = (item.name || "").trim();
  if (!name || name.length < 4) return null;

  const letters = name.replace(/[^a-zA-Z]/g, "");
  if (letters.length < 3) return null;
  const upperRatio = letters.replace(/[^A-Z]/g, "").length / letters.length;
  if (upperRatio < 0.6) return null;

  if (name === name.toUpperCase() && name.length < 8) return null;
  if (["APPETIZERS", "ENTREES", "DESSERTS", "MAIN COURSES"].includes(name)) return null;

  const titleCased = name.replace(
    /\b\w+/g,
    (w) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()
  );

  if (titleCased === name) return null;

  return {
    item_index: index,
    field: "name",
    reason: `All-caps name normalized to title case`,
    old_value: name,
    new_value: titleCased,
    confidence: 0.8,
  };
}

// ── Public API ──

export function correctItem(
  item: StewardItem,
  index: number,
  allItems: StewardItem[]
): { item: StewardItem; corrections: Correction[] } {
  const corrections: Correction[] = [];
  const corrected = { ...item };

  const nameFix = fixTrailingPunctuation(corrected, index);
  if (nameFix) {
    corrections.push(nameFix);
    corrected.name = nameFix.new_value as string;
  }

  const caseFix = fixTitleCase(corrected, index);
  if (caseFix) {
    corrections.push(caseFix);
    corrected.name = caseFix.new_value as string;
  }

  const priceFix = fixPriceDecimal(corrected, index);
  if (priceFix) {
    corrections.push(priceFix);
    corrected.price = priceFix.new_value as number;
  }

  // 3a. Fix price that's a statistical outlier for its category
  const outlierFix = fixPriceOutlier(corrected, index);
  if (outlierFix) {
    corrections.push(outlierFix);
    corrected.price = outlierFix.new_value as number;
  }

  const descFix = fixEmptyDescription(corrected, index);
  if (descFix) {
    corrections.push(descFix);
    corrected.description = descFix.new_value as string;
  }

  const swapFix = fixDescriptionMismatch(corrected, index, allItems);
  if (swapFix) {
    corrections.push(swapFix);
    corrected.description = swapFix.new_value as string;
  }

  const catFix = fixCategory(corrected, index);
  if (catFix) {
    corrections.push(catFix);
    corrected.category = catFix.new_value as string;
  }

  return { item: corrected, corrections };
}

export function correctItems(
  items: StewardItem[]
): { items: StewardItem[]; corrections: Correction[] } {
  const allCorrections: Correction[] = [];
  const corrected = items.map((item, index) => {
    const result = correctItem(item, index, items);
    allCorrections.push(...result.corrections);
    return result.item;
  });

  return { items: corrected, corrections: allCorrections };
}
