import { logger } from "@/lib/logger";

interface OpenFoodFactsProduct {
  product_name?: string;
  categories?: string;
  categories_tags?: string[];
  ingredients_text?: string;
  nutrition_grades?: string;
  labels?: string;
  labels_tags?: string[];
  allergens?: string;
  nova_group?: number;
  food_groups?: string;
}

interface OpenFoodFactsResponse {
  count: number;
  products: OpenFoodFactsProduct[];
}

export interface OpenFoodFactsInfo {
  categories: string[];
  ingredients: string;
  nutritionGrade: string;
  labels: string[];
}

export async function searchOpenFoodFacts(
  dishName: string
): Promise<OpenFoodFactsInfo | null> {
  try {
    // Search by dish name
    const url = `https://world.openfoodfacts.org/cgi/search.pl?search_terms=${encodeURIComponent(dishName)}&search_simple=1&action=process&json=true&page_size=3`;
    const res = await fetch(url, {
      headers: {
        "User-Agent": "MenuLens/1.0 (https://github.com/menu-lens; menulens@example.com)",
        Accept: "application/json",
      },
      signal: AbortSignal.timeout(8000),
    });

    if (!res.ok) {
      logger.warn(`[OpenFoodFacts] HTTP ${res.status} for "${dishName}"`);
      return null;
    }

    const data: OpenFoodFactsResponse = await res.json();
    if (!data.products || data.products.length === 0) {
      logger.info(`[OpenFoodFacts] No results for "${dishName}"`);
      return null;
    }

    const product = data.products[0];
    const info: OpenFoodFactsInfo = {
      categories: (product.categories_tags || [])
        .filter((c) => !c.startsWith("en:"))
        .slice(0, 5),
      ingredients: product.ingredients_text || "",
      nutritionGrade: product.nutrition_grades || "",
      labels: (product.labels_tags || [])
        .filter((l) => !l.startsWith("en:"))
        .slice(0, 5),
    };

    logger.info(`[OpenFoodFacts] Found data for "${dishName}"`);
    return info;
  } catch {
    logger.warn(`[OpenFoodFacts] Error for "${dishName}"`);
    return null;
  }
}
