// ── Steward Agent — Orchestrator ──
// Runs the full validation → correction → memory cycle on every scan.
// Called from the scan API endpoint — zero UI footprint.

import { StewardItem, StewardRecord, Correction, StewardConfig, DEFAULT_STEWARD_CONFIG } from "./types";
import { validateItems, computeQualityScore } from "./validator";
import { correctItems } from "./corrector";
import { getStewardMemory } from "./memory";
import { logger } from "@/lib/logger";

export interface StewardResult {
  /** Corrected items (or originals if auto_correct is off) */
  items: StewardItem[];
  /** All corrections that were applied */
  corrections: Correction[];
  /** Validation results for debugging */
  validations: ReturnType<typeof validateItems>;
  /** Overall quality score (0-100) */
  qualityScore: number;
  /** Whether any corrections were made */
  wasCorrected: boolean;
  /** Machine-readable record for storage */
  record: StewardRecord;
}

/**
 * Run the full steward cycle on a set of scan items.
 * This is the main entry point called after OCR extraction.
 */
export function runSteward(
  items: StewardItem[],
  scanId: string,
  imageHash?: string,
  config?: Partial<StewardConfig>
): StewardResult {
  const cfg = { ...DEFAULT_STEWARD_CONFIG, ...config };
  const start = Date.now();

  // Step 1: Validate
  const validations = validateItems(items);

  // Step 2: Compute base quality score
  const baseQuality = computeQualityScore(validations);

  // Step 3: Correct (if enabled)
  let correctedItems = [...items];
  let corrections: Correction[] = [];

  if (cfg.auto_correct) {
    const result = correctItems(correctedItems);
    correctedItems = result.items;
    corrections = result.corrections;
  }

  // Step 4: Re-validate after correction to get final quality
  const finalValidations = corrections.length > 0
    ? validateItems(correctedItems)
    : validations;
  const finalQuality = computeQualityScore(finalValidations);

  // Step 5: Record to memory
  const record: StewardRecord = {
    scan_id: scanId,
    timestamp: new Date().toISOString(),
    image_hash: imageHash,
    item_count: items.length,
    validations: finalValidations,
    corrections,
    quality_score: finalQuality,
  };

  const memory = getStewardMemory();
  memory.recordScan(record);

  const elapsed = Date.now() - start;
  if (corrections.length > 0) {
    logger.info({
      msg: `Steward: ${corrections.length} correction(s) applied in ${elapsed}ms`,
      scanId,
      quality: `${baseQuality}→${finalQuality}`,
      corrections: corrections.map((c) => `${c.field}=${c.reason.slice(0, 60)}`),
    });
  } else if (baseQuality < 60) {
    logger.info({
      msg: `Steward: low quality (${baseQuality}%) but no corrections available`,
      scanId,
    });
  }

  return {
    items: correctedItems,
    corrections,
    validations: finalValidations,
    qualityScore: finalQuality,
    wasCorrected: corrections.length > 0,
    record,
  };
}

/**
 * Get a summary of steward activity.
 */
export function getStewardSummary(): string {
  const memory = getStewardMemory();
  return memory.getSummary();
}
