import { searchDishImages } from "@/lib/images";
import { chatCompletions } from "@/lib/ai/client";
import { searchOpenFoodFacts } from "@/lib/images/openfoodfacts";

export interface DishResearch {
  name: string;
  description: string;
  origin: string;
  dietary_tags: string[];
  images: { url: string; title?: string }[];
}

export async function researchDish(dishName: string): Promise<DishResearch> {
  const [imageResults, webInfo] = await Promise.allSettled([
    searchDishImages(dishName, 3),
    getDishInfo(dishName),
  ]);

  const imageData =
    imageResults.status === "fulfilled" ? imageResults.value : null;
  const images = imageData
    ? imageData.images.map((img) => ({ url: img.url, title: img.title }))
    : [];

  const info =
    webInfo.status === "fulfilled"
      ? webInfo.value
      : { description: "", origin: "", dietary_tags: [] };

  return {
    name: dishName,
    description: info.description,
    origin: info.origin,
    dietary_tags: info.dietary_tags,
    images,
  };
}

interface DishInfo {
  description: string;
  origin: string;
  dietary_tags: string[];
}

const WIKI_SUMMARY_URL = "https://en.wikipedia.org/api/rest_v1/page/summary";
const MEALDB_BASE_URL = "https://www.themealdb.com/api/json/v1/1";

interface WikiSummary {
  description?: string;
  extract?: string;
}

interface MealDBMeal {
  strMeal: string;
  strCategory: string;
  strArea: string;
  strInstructions: string;
}

async function searchWikipediaSummary(
  dishName: string
): Promise<{ description: string; origin: string } | null> {
  try {
    const searchUrl = `https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch=${encodeURIComponent(dishName + " food dish")}&srlimit=3&format=json&origin=*`;
    const searchRes = await fetch(searchUrl, {
      headers: { "User-Agent": "MenuLens/1.0 (https://github.com/menu-lens)" },
    });
    if (!searchRes.ok) return null;

    const searchData = await searchRes.json();
    const results = searchData.query?.search || [];
    if (results.length === 0) return null;

    const title = results[0].title;
    const summaryUrl = `${WIKI_SUMMARY_URL}/${encodeURIComponent(title)}`;
    const summaryRes = await fetch(summaryUrl, {
      headers: { "User-Agent": "MenuLens/1.0 (https://github.com/menu-lens)" },
    });
    if (!summaryRes.ok) return null;

    const summary: WikiSummary = await summaryRes.json();
    const description = summary.description || summary.extract || "";
    const origin = summary.extract?.match(/(?:from|originating in|native to|popular in) ([A-Za-z][a-z]+(?: [A-Za-z][a-z]+)*)/)?.[1] ||
      summary.extract?.match(/originated? (?:in|from) ([A-Z][a-z]+(?: [A-Z][a-z]+)*)/)?.[1] ||
      summary.extract?.match(/native to ([A-Z][a-z]+(?: [A-Z][a-z]+)*)/)?.[1] || "";

    if (description.length > 10) {
      return { description: description.slice(0, 300), origin };
    }
    return null;
  } catch {
    return null;
  }
}

async function searchMealDBInfo(
  dishName: string
): Promise<{ description: string; origin: string; dietary_tags: string[] } | null> {
  try {
    const res = await fetch(
      `${MEALDB_BASE_URL}/search.php?s=${encodeURIComponent(dishName)}`,
      {
        headers: { "User-Agent": "MenuLens/1.0 (https://github.com/menu-lens)" },
      }
    );
    if (!res.ok) return null;

    const data = await res.json();
    const meal: MealDBMeal | undefined = data.meals?.[0];
    if (!meal) return null;

    const description = meal.strInstructions
      ? meal.strInstructions.split("\n")[0].slice(0, 300)
      : "";
    const origin = meal.strArea || "";
    const category = meal.strCategory || "";
    const dietary_tags: string[] = [];
    if (category.toLowerCase().includes("vegetarian")) dietary_tags.push("vegetarian");
    if (category.toLowerCase().includes("vegan")) dietary_tags.push("vegan");
    if (category.toLowerCase().includes("seafood")) dietary_tags.push("seafood");
    if (category.toLowerCase().includes("chicken") || category.toLowerCase().includes("beef") || category.toLowerCase().includes("pork"))
      dietary_tags.push("protein");

    if (description.length > 10 || origin.length > 0) {
      return { description, origin, dietary_tags };
    }
    return null;
  } catch {
    return null;
  }
}

async function generateAIDescription(dishName: string): Promise<string> {
  try {
    const response = await chatCompletions({
      messages: [
        {
          role: "system",
      content:
        "You are a food expert. Write a 1-2 sentence factual description of the dish. Include what it is, key ingredients, cooking method, and origin if known. Keep it concise and accurate. If the dish is obscure or unknown, describe it generically as a menu item without admitting lack of knowledge.",
        },
        {
          role: "user",
          content: `Describe ${dishName} in 1-2 sentences.`,
        },
      ],
      temperature: 0.3,
      max_tokens: 150,
    });
    const content = response.choices[0]?.message?.content?.trim() || "";
    if (!content || content.length < 5) return "";
    return content;
  } catch {
    return "";
  }
}

export async function getDishInfo(dishName: string): Promise<DishInfo> {
  const [wikiResult, mealResult, openFoodResult, aiResult] = await Promise.allSettled([
    searchWikipediaSummary(dishName),
    searchMealDBInfo(dishName),
    searchOpenFoodFacts(dishName),
    generateAIDescription(dishName),
  ]);

  const wiki = wikiResult.status === "fulfilled" ? wikiResult.value : null;
  const meal = mealResult.status === "fulfilled" ? mealResult.value : null;
  const openFood = openFoodResult.status === "fulfilled" ? openFoodResult.value : null;
  const ai = aiResult.status === "fulfilled" ? aiResult.value : "";

  // Build dietary tags from Open Food Facts
  const dietaryFromOpenFood: string[] = [];
  if (openFood) {
    const cats = openFood.categories.join(" ").toLowerCase();
    const labels = openFood.labels.join(" ").toLowerCase();
    if (cats.includes("vegetarian") || labels.includes("vegetarian")) dietaryFromOpenFood.push("vegetarian");
    if (cats.includes("vegan") || labels.includes("vegan")) dietaryFromOpenFood.push("vegan");
    if (cats.includes("gluten") || labels.includes("gluten-free")) dietaryFromOpenFood.push("gluten-free");
    if (cats.includes("organic") || labels.includes("organic")) dietaryFromOpenFood.push("organic");
  }

  if (meal) {
    return {
      description: meal.description || ai || `${dishName}. A menu item whose details are being researched.`,
      origin: meal.origin || (openFood?.categories[0] || ""),
      dietary_tags: [...new Set([...meal.dietary_tags, ...dietaryFromOpenFood])],
    };
  }

  if (wiki) {
    return {
      description: wiki.description || ai || `${dishName}. A menu item whose details are being researched.`,
      origin: wiki.origin,
      dietary_tags: dietaryFromOpenFood,
    };
  }

  return {
    description: ai || `${dishName}. A menu item whose details are being researched.`,
    origin: openFood?.categories[0] || "",
    dietary_tags: dietaryFromOpenFood,
  };
}
