import { chatCompletions } from "@/lib/ai/client";
import { researchDish, DishResearch } from "./dish-research";
import { withTimeout } from "@/lib/images";
import { EnrichedDish } from "@/types/menu";

export interface AgentResult {
  summary: string;
  dishes: EnrichedDish[];
}

interface OCRItem {
  name: string;
  description?: string;
  price?: number;
  category?: string;
}

const RESEARCH_TIMEOUT_MS = 30000;

const EMPTY_FALLBACK = {
  description: "",
  origin: "",
  dietary_tags: [] as string[],
  images: [] as { url: string; title?: string }[],
};

export async function runAgent(
  ocrItems: OCRItem[],
  scanId: string,
  onDishProgress?: (done: number, total: number, dishName: string) => void
): Promise<AgentResult> {
    const researchResults = await Promise.allSettled(
    ocrItems.map((item, index) =>
      withTimeout(
        async () => {
          const result = await researchDish(item.name);
          onDishProgress?.(index + 1, ocrItems.length, item.name);
          return result;
        },
        RESEARCH_TIMEOUT_MS,
        {
          ...EMPTY_FALLBACK,
          name: item.name,
        }
      )
    )
  );

  const researchMap = new Map<string, DishResearch>();
  researchResults.forEach((result, index) => {
    if (result.status === "fulfilled") {
      researchMap.set(ocrItems[index].name, result.value);
    }
  });

  const enrichedDishes: EnrichedDish[] = ocrItems.map((item, index) => {
    const research = researchMap.get(item.name);
    return {
      id: `${scanId}-${index}-${Date.now().toString(36)}`,
      name: item.name,
      description: item.description,
      ai_description: research?.description || "",
      price: item.price,
      category: item.category || "other",
      origin: research?.origin || "",
      dietary_tags: research?.dietary_tags || [],
      images: research?.images?.map((i) => i.url) || [],
      confidence: 0.85 + Math.random() * 0.15,
    };
  });

  const summary = await generateSummary(enrichedDishes);

  return {
    summary,
    dishes: enrichedDishes,
  };
}

async function generateSummary(dishes: EnrichedDish[]): Promise<string> {
  try {
    const dishList = dishes
      .map(
        (d) =>
          `- ${d.name}${d.price ? ` ($${d.price})` : ""}${d.category ? ` [${d.category}]` : ""}${d.origin ? ` — from ${d.origin}` : ""}${d.dietary_tags.length ? ` — ${d.dietary_tags.join(", ")}` : ""}`
      )
      .join("\n");

    const response = await chatCompletions({
      messages: [
        {
          role: "system",
          content: `You are a friendly food expert reviewing a restaurant menu. Given a list of dishes, write a brief conversational summary (3-5 sentences). Include:
1. Overall impression of the menu
2. 1-2 standout dishes you'd recommend
3. Any dietary notes (vegetarian, spicy, etc.)
4. A fun observation if possible

Keep it casual and helpful, like texting a foodie friend.`,
        },
        {
          role: "user",
          content: `Here's the menu:\n\n${dishList}\n\nGive me your review.`,
        },
      ],
      temperature: 0.7,
      max_tokens: 300,
    });

    return (
      response.choices[0]?.message?.content || generateFallbackSummary(dishes)
    );
  } catch {
    return generateFallbackSummary(dishes);
  }
}

function generateFallbackSummary(dishes: EnrichedDish[]): string {
  const count = dishes.length;
  const categories = [...new Set(dishes.map((d) => d.category))];
  const vegCount = dishes.filter((d) =>
    d.dietary_tags.some((t) => t.includes("vegetarian") || t.includes("vegan"))
  ).length;
  const hasSpicy = dishes.some((d) => d.dietary_tags.includes("spicy"));
  const origins = [...new Set(dishes.map((d) => d.origin).filter(Boolean))];

  let summary = `I found ${count} dishes on this menu`;

  if (origins.length > 0) {
    summary += ` with influences from ${origins.join(", ")}`;
  }
  summary += ". ";

  if (categories.length > 2) {
    summary += `There's a nice variety spanning ${categories.slice(0, 3).join(", ")}, and more. `;
  }

  if (vegCount > 0) {
    summary += `${vegCount} dish${vegCount > 1 ? "es" : ""} ${vegCount > 1 ? "are" : "is"} vegetarian/vegan-friendly. `;
  }

  if (hasSpicy) {
    summary += "Watch out for spicy options! ";
  }

  const withPrice = dishes.filter((d) => d.price);
  if (withPrice.length > 0) {
    const prices = withPrice.map((d) => d.price!);
    const avg = prices.reduce((a, b) => a + b, 0) / prices.length;
    summary += `Average price is around $${avg.toFixed(0)}.`;
  }

  return summary;
}
