// ── Steward Agent Types ──
// The invisible background agent that validates, corrects, and learns
// from every scan result.

export interface StewardItem {
  name: string;
  description: string;
  price: number | null;
  category?: string;
  confidence: number;
  [key: string]: unknown;
}

/** Result of a single validation check */
export interface ValidationCheck {
  field: string;
  passed: boolean;
  severity: "info" | "warn" | "error";
  message: string;
  original_value?: unknown;
  suggested_value?: unknown;
}

/** Complete validation result for one item */
export interface ItemValidation {
  item_index: number;
  item_name: string;
  checks: ValidationCheck[];
  overall: "pass" | "warn" | "fail";
}

/** A correction applied by the steward */
export interface Correction {
  item_index: number;
  field: "name" | "description" | "price" | "category" | "confidence";
  reason: string;
  old_value: unknown;
  new_value: unknown;
  confidence: number; // how sure the steward was (0-1)
}

/** A complete steward observation record */
export interface StewardRecord {
  scan_id: string;
  timestamp: string;
  image_hash?: string;
  item_count: number;
  validations: ItemValidation[];
  corrections: Correction[];
  quality_score: number; // 0-100 overall quality score
}

/** Summary for the training core */
export interface TrainingSample {
  pattern: string; // e.g. "trailing-dot-in-name", "price-too-high-for-category"
  count: number;
  last_seen: string;
  fix_rate: number; // how often the correction was applied
}

/** Steward configuration */
export interface StewardConfig {
  /** Max reasonable price for a single dish (above this is likely misread) */
  max_reasonable_price: number;
  /** Price outlier z-score threshold */
  price_z_threshold: number;
  /** Minimum name length after which we suspect a misread */
  min_name_length: number;
  /** Enable auto-correction */
  auto_correct: boolean;
  /** Storage path for memory */
  storage_path: string;
}

export const DEFAULT_STEWARD_CONFIG: StewardConfig = {
  max_reasonable_price: 200,
  price_z_threshold: 2.5,
  min_name_length: 2,
  auto_correct: true,
  storage_path: ".steward/memory.json",
};
